                    added = trace.read(2 * 1024 * 1024)
                    trace_offset = trace.tell()
                trace_pending += added
                while '\n' in trace_pending:
                    line, trace_pending = trace_pending.split('\n', 1)
                    if not line.strip():
                        continue
                    row = json.loads(line)
                    tool = row.get('toolResult') or {}
                    trace_observations.append({'observedMs': elapsed_ms(), 'iteration': row.get('iteration'), 'action': tool.get('action'), 'durationMs': tool.get('durationMs'), 'failure': row.get('failure'), 'recovery': row.get('recovery')})
        watched = list(streams)
        if stdin_open:
            watched.append(sys.stdin)
        ready, _, _ = select.select(watched, [], [], 0.05)
        for stream in ready:
            if stream is sys.stdin:
                chunk = os.read(sys.stdin.fileno(), 4096)
                if not chunk:
                    stdin_open = False
                    process.stdin.close()
                    continue
                pending_input += chunk
                while b'\n' in pending_input:
                    line, pending_input = pending_input.split(b'\n', 1)
                    choice = line.decode().strip()
                    approvals.append({'elapsedMs': elapsed_ms(), 'choice': choice, 'candidate': candidate})
                    if choice == 'approve' and candidate == 'CALL_CODEX':
                        worker_approval_ms = elapsed_ms()
                process.stdin.write(chunk)
                process.stdin.flush()
                continue
            chunk = os.read(stream.fileno(), 65536)
            if not chunk:
                del streams[stream]
                continue
            stream_name, log = streams[stream]
            remaining = max(0, 8 * 1024 * 1024 - counts[stream_name])
            log.write(chunk[:remaining])
            log.flush()
