                if matches:
                    candidate = matches[-1]
            elif stream_name == 'stdout' and not output_limit:
                pending_stdout += chunk
                while b'\n' in pending_stdout:
                    line, pending_stdout = pending_stdout.split(b'\n', 1)
                    if not line.strip():
                        continue
