  };
};

export type ClaudeProposal = {
  action: 'CALL_CLAUDE';
  tool: 'claude_code_cli';
  input: {
    root: string;
    task: string;
    context: WorkerContext;
  };
};

export type AskUserProposal = {
  action: 'ASK_USER';
