import { describe, it, expect } from "vitest";
import { truncateAddress } from "./format";

describe("truncateAddress", () => {
  it("truncates a 56-character Stellar address", () => {
    const addr = "G" + "A".repeat(51) + "WXYZ";
    expect(addr).toHaveLength(56);
    expect(truncateAddress(addr)).toBe("GAAAAA...WXYZ");
  });

  it("returns an empty string for empty input", () => {
    expect(truncateAddress("")).toBe("");
  });

  it("returns an empty string for undefined-like input", () => {
    expect(truncateAddress(undefined as unknown as string)).toBe("");
    expect(truncateAddress(null as unknown as string)).toBe("");
  });

  it("returns a 1-character string unchanged", () => {
    expect(truncateAddress("G")).toBe("G");
  });

  it("returns a short string unchanged instead of overlapping", () => {
    expect(truncateAddress("GABCD")).toBe("GABCD");
  });

  it("returns a 10-character string unchanged", () => {
    expect(truncateAddress("GABCDEFGHI")).toBe("GABCDEFGHI");
  });

  it("truncates an 11-character string", () => {
    expect(truncateAddress("GABCDEFGHIJ")).toBe("GABCDE...GHIJ");
  });
});

